files.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
img, video { max-width: 100%; height: auto; }
a { color: #125a46; }

.dashboard { margin: 0 auto; max-width: 900px; }
.dashboard > * { padding: 12px; border-radius: 8px; background: white; }
.links a { display: block; }
.cards article { padding: 8px; background: #e6f4ee; border-radius: 6px; }
.cards h3 { margin: 0; }

.dashboard { display: grid; gap: 12px; grid-template-columns: 160px minmax(0, 1fr); }
#top { grid-column: 1 / -1; }
.cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }

files.script.js:
const equipment = [
  { name: 'Laser Kit', room: 'design', minutes: 35 },
  { name: 'Tripod Kit', room: 'photo', minutes: 10 },
  { name: 'Softbox', room: 'photo', minutes: 25 },
  { name: 'Sketch Kit', room: 'design', minutes: 15 },
];

const query = document.querySelector('#query');
const room = document.querySelector('#room');
const order = document.querySelector('#order');
const listing = document.querySelector('#equipment');
const count = document.querySelector('#count');

function render() {
  const term = query.value.trim().toLowerCase();
  const filtered = equipment.filter((item) =>
    item.name.toLowerCase().includes(term) || (room.value === 'all' || item.room === room.value)
  );
  const direction = order.value === 'desc' ? -1 : 1;
  const sorted = filtered.toSorted((first, second) => direction * (first.minutes - second.minutes));
  listing.replaceChildren();
  for (const item of sorted) {
    const row = document.createElement('li');
    row.textContent = item.name + ' · ' + item.minutes + ' 分钟';
    listing.append(row);
  }
  count.textContent = sorted.length ? `共 ${sorted.length} 项` : '没有匹配器材';
}

query.addEventListener('input', render);
room.addEventListener('change', render);
order.addEventListener('change', render);
render();

const reader = document.querySelector('#reader');
const toggle = document.querySelector('#theme-toggle');

function showTheme(theme) {
  reader.dataset.theme = theme;
  toggle.setAttribute('aria-pressed', String(theme === 'dark'));
}

showTheme('light');
toggle.addEventListener('click', () => {
  const nextTheme = reader.dataset.theme === 'dark' ? 'light' : 'dark';
  showTheme(nextTheme);
  localStorage.setItem('reader-theme', nextTheme);
});

const fixtures = {
  main: { notices: [
    { title: '采集体验', room: '摄影室' },
    { title: '<复核>购置清单', room: '设备库' },
  ] },
  empty: { notices: [] },
};

function localUrl(kind) {
  if (kind === 'error') return 'data:application/json,%7B';
  return 'data:application/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(fixtures[kind]));
}

function simulateWait() {
  return new Promise((resolve) => setTimeout(resolve, 200));
}

const sample = document.querySelector('#demo');
const button = document.querySelector('#refresh');
const state = document.querySelector('#state');
const notices = document.querySelector('#notices');

button.addEventListener('click', async () => {
  button.disabled = true;
  state.textContent = '加载中';
  notices.replaceChildren();
  const url = localUrl(sample.value);
  try {
    await simulateWait();
    const response = await fetch(url);
    if (!response.ok) throw new Error('读取失败');
    const { notices: records } = await response.json();
    for (const record of records) {
      const item = document.createElement('li');
      item.textContent = record.title + ' · ' + record.room;
      notices.append(item);
    }
    state.textContent = records.length ? `已加载 ${records.length} 条` : '暂无通知';
    button.disabled = false;
  } catch {
    state.textContent = '无法读取通知，请重试';
  }
});
